import gen,numpy as np,cv2
from rcb_brush import Session
s=Session(instance=gen.INSTANCE,render=False);s.reset()
for a in np.load('/app/output/trajectory.npz')['actions']:s.step(a)
records=s.strokes(); target=gen.target_geometry(s)[0]
items=[]
for r in records:
 r0,c0=r['mask_bbox'];m=r['mask']>=128
 items.append([int(r0),int(c0),m.copy(),0])
def draw(it):
 r,c,m,rad=it
 pad=max(0,rad)+1
 a=np.zeros((m.shape[0]+2*pad,m.shape[1]+2*pad),np.uint8);a[pad:pad+m.shape[0],pad:pad+m.shape[1]]=m
 if rad>0:a=cv2.dilate(a,cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*rad+1,2*rad+1)))
 elif rad<0:a=cv2.erode(a,cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*(-rad)+1,2*(-rad)+1)))
 yy,xx=np.where(a>0);r0=r-pad;c0=c-pad
 o=np.zeros((1024,1024),bool); good=(yy+r0>=0)&(yy+r0<1024)&(xx+c0>=0)&(xx+c0<1024);o[yy[good]+r0,xx[good]+c0]=1
 return o
def score(items):
 a=np.zeros((1024,1024),bool)
 for it in items:a|=draw(it)
 x=(a&target).sum();return x/(a.sum()+target.sum()-x+1e-9),a.sum()
print('initial',score(items))
cache=[{} for _ in items]
for i,it in enumerate(items):
 for rad in range(-3,7):
  if rad==0:cache[i][rad]=draw([it[0],it[1],it[2],0])
  else:cache[i][rad]=draw([it[0],it[1],it[2],rad])
for sweep in range(2):
 for i,it in enumerate(items):
  others=np.zeros((1024,1024),bool)
  for j,ot in enumerate(items):
   if i!=j:others|=cache[j][ot[3]]
  best=(-1,0)
  for rad,mask in cache[i].items():
   union=others|mask; inter=(union&target).sum();sc=inter/(union.sum()+target.sum()-inter+1e-9)
   if sc>best[0]:best=(sc,rad)
  it[3]=best[1]
 print('sweep',sweep,score(items),'radii',[it[3] for it in items])
