import numpy as np,cv2,json
from rcb_brush import Session
path='/tmp/lookahead_output/trajectory.npz'
s=Session(instance='/app/instance.json',render=False);s.reset()
for a in np.load(path)['actions']: s.step(a)
records=s.strokes();target=cv2.cvtColor(s.target_image(),cv2.COLOR_RGB2GRAY)<132
items=[]
for r in records:
 y,x=r['mask_bbox'];m=r['mask']>=128;items.append([int(y),int(x),m.copy()])
def draw(item):
 y,x,m=item;out=np.zeros((1024,1024),bool);h,w=m.shape;y0=max(0,y);x0=max(0,x);y1=min(1024,y+h);x1=min(1024,x+w)
 if y1>y0 and x1>x0:out[y0:y1,x0:x1]=m[y0-y:y1-y,x0-x:x1-x]
 return out
def metrics(items):
 ink=np.zeros_like(target)
 for it in items: ink|=draw(it)
 inter=(ink&target).sum();return inter/(ink.sum()+target.sum()-inter+1e-9),ink.sum(),inter
print('initial',metrics(items))
for sweep in range(3):
 moved=0
 for i,it in enumerate(items):
  others=np.zeros_like(target)
  for j,other in enumerate(items):
   if j!=i:others|=draw(other)
  oa=int(others.sum());oi=int((others&target).sum())
  y,x,m=it;h,w=m.shape;best=(-1,0,0)
  for dy in range(-8,9):
   for dx in range(-8,9):
    yy=y+dy;xx=x+dx;y0=max(0,yy);x0=max(0,xx);y1=min(1024,yy+h);x1=min(1024,xx+w)
    if y1<=y0 or x1<=x0:continue
    mm=m[y0-yy:y1-yy,x0-xx:x1-xx];o=others[y0:y1,x0:x1];t=target[y0:y1,x0:x1];added=mm&~o
    area=oa+int(added.sum());inter=oi+int((added&t).sum());sc=inter/(area+target.sum()-inter+1e-9)
    if sc>best[0]:best=(sc,dx,dy)
  if best[1] or best[2]:moved+=1;it[0]+=best[2];it[1]+=best[1]
  print(sweep+1,i+1,best[1],best[2],round(best[0],4))
 print('sweep',sweep+1,metrics(items),'moved',moved)
base=[]
for r in records:base.append([int(r['mask_bbox'][1]),int(r['mask_bbox'][0])])
deltas=[[it[1]-base[i][0],it[0]-base[i][1]] for i,it in enumerate(items)]
print('deltas',json.dumps(deltas))
